jest.mock('./client', () => ({
  fetchUser: jest.fn(),
}));

import {fetchUser} from './client';
import {getUserName} from './user';

test('uses the mocked client', async () => {
  jest.mocked(fetchUser).mockResolvedValue({name: 'Ada'});
  await expect(getUserName('1')).resolves.toBe('Ada');
  expect(fetchUser).toHaveBeenCalledWith('1');
});

const api = {
  fetchUser: () => ({name: "Ada"}),
};

test("uses a temporary implementation", () => {
  const spy = jest.spyOn(api, "fetchUser")
    .mockImplementation(() => ({name: "Grace"}));

  expect(api.fetchUser()).toEqual({name: "Grace"});
  expect(spy).toHaveBeenCalledTimes(1);

  spy.mockRestore();
  expect(api.fetchUser()).toEqual({name: "Ada"});
});

